// Generates the markdown documents of handoff/ENTRY_CORE_V4 from results/v4_results.json (machine-derived tables + narrative quoting the same numbers).
import { readFileSync, writeFileSync, mkdirSync, copyFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
const HERE = dirname(fileURLToPath(import.meta.url)); const REPO = join(HERE, '..', '..', '..'); const ROOT = join(REPO, 'research', 'entry_core_v4'); const R = JSON.parse(readFileSync(join(ROOT, 'results', 'v4_results.json'), 'utf8')); const DEFN = R.finalist_definitions; const OUT = join(REPO, 'handoff', 'ENTRY_CORE_V4'); mkdirSync(OUT, { recursive: true });
const f = (x, d = 3) => (x == null ? '—' : typeof x === 'number' ? (Number.isInteger(x) ? String(x) : x.toFixed(d)) : String(x)); const ci = (c) => (c ? `[${f(c[0])}, ${f(c[1])}]` : '—'); const pc = (x) => (x == null ? '—' : `${(x * 100).toFixed(1)} %`); const S2 = ['DEV', 'HOLD']; const W = (name, md) => writeFileSync(join(OUT, name), md);
const CANDS = DEFN.candidates; const FAMNAME = { A: 'COMPRESSION → EXPANSION', B: 'LIQUIDITY SWEEP → RECLAIM', C: 'STRUCTURE BREAK → CONFIRMATION', D: 'PULLBACK → CONTINUATION', E: 'MOMENTUM IGNITION', F: 'RANGE BREAK → ACCEPTANCE', G: 'TREND RESUMPTION' }; const SNAME = Object.fromEntries(Object.entries(DEFN.finalists).map(([k, v]) => [k, `${k} (${FAMNAME[v.family]}: ${v.grid_key})`]));
const HC = R.HOLD.control, DC = R.DEV.control, DEC = R.decisions, BEST = DEC.best_candidate, HB = R.HOLD.candidates[BEST], DB = R.DEV.candidates[BEST];
const cellRow = (k, v) => `| ${k} | ${v.n}${v.n < 30 ? ' (INSUFFICIENT)' : ''} | ${pc(v.win_rate)} | ${f(v.expectancy_r)} | ${f(v.pf, 2)} | ${f(v.mfe_r, 2)} / ${f(v.mae_r, 2)} | ${ci(v.ci95_r)} |`; const CELLH = '| Segment | N | Win rate | Expectancy (R) | PF | MFE / MAE (R) | 95 % CI |\n|---|---|---|---|---|---|---|';
const FINH = '| Candidate | Signals | Trades | Win | Exp (R) | Exp (USD @0.01) | PF | Max DD (R) | Trade 95 % CI | Block 95 % CI | Stress | Drift | Quarters > 0 | Trades/session (median) | Move capture | FP rate (24 bars) |\n|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|';
const finRow = (S, k) => { const v = k === 'CONTROL' ? R[S].control : R[S].candidates[k]; return `| ${k === 'CONTROL' ? 'CONTROL' : SNAME[k] ?? k} | ${v.signals} | ${v.n} | ${pc(v.win_rate)} | ${f(v.expectancy_r)} | ${f(v.expectancy_usd, 2)} | ${f(v.pf, 2)} | ${f(v.max_dd_r, 2)} | ${ci(v.ci95_r)} | ${ci(v.block_ci95_r)} | ${f(v.stress.expectancy_r)} | ${f(v.drift.expectancy_r)} | ${pc(v.quarters_positive_share)} | ${f(v.trades_per_session?.median)} | ${pc(v.move_capture.capture_rate)} | ${pc(v.false_move.fp_rate_24)} |`; };
const finTable = (S) => `${FINH}\n${['CONTROL', ...CANDS].map((k) => finRow(S, k)).join('\n')}`;
const forRow = (S, k) => { const v = R[S].candidates[k]; const r = v.forensics.rates; return `| ${SNAME[k]} | ${pc(r.VALID)} | ${pc(r.LATE)} | ${pc(r.WRONG_DIRECTION)} | ${pc(r.ALREADY_POSITIONED)} | ${pc(r.TRIGGER_BLOCKED)} | ${pc(r.SETUP_NO_TRIGGER)} | ${pc(r.NO_SETUP)} | ${pc(r.NO_SETUP + r.SETUP_NO_TRIGGER)} | ${Object.entries(v.forensics.block_reasons).map(([a, b]) => `${a} ${b}`).join(', ') || '—'} | ${f(v.forensics.earliest_setup_rel_onset.median)} / ${pc(v.forensics.earliest_setup_rel_onset.at_or_before_onset)} | ${f(v.forensics.earliest_trigger_rel_onset.median)} / ${pc(v.forensics.earliest_trigger_rel_onset.at_or_before_onset)} |`; };
const ctlForRow = (S) => { const m = R[S].control.move_capture; return `| CONTROL (production) | ${pc(m.valid_entry_rate)} | ${pc(m.late_entry_rate)} | ${pc(m.wrong_direction_rate)} | ${pc(m.already_positioned_rate)} | ${pc(m.gate_or_filter_rate)} (production gates) | — | — | ${pc(m.no_setup_or_trigger_rate)} (combined) | — | — | — |`; };
const FORH = '| Candidate | VALID (≤ onset) | LATE | WRONG_DIRECTION | ALREADY_POSITIONED | TRIGGER_BLOCKED | SETUP_NO_TRIGGER | NO_SETUP | NO_SETUP + NO_TRIGGER | Block reasons | Earliest setup: median bars vs onset / share ≤ onset | Earliest trigger: median / share ≤ onset |\n|---|---|---|---|---|---|---|---|---|---|---|---|';

// ---------- CONTROL / provenance / event definition ----------
W('V4_CONTROL_BASELINE.md', readFileSync(join(ROOT, 'V4_CONTROL_BASELINE.md'), 'utf8') + `\n## Reproduction (asserted by the study)\n| Split | n | Exp (R) | PF | DD (R) | Capture | NO_SETUP_OR_TRIGGER | Wrong direction | FP rate (24 bars) |\n|---|---|---|---|---|---|---|---|---|\n${S2.map((S) => { const c = R[S].control; return `| ${S} | ${c.n} | ${f(c.expectancy_r)} | ${f(c.pf, 2)} | ${f(c.max_dd_r, 2)} | ${pc(c.move_capture.capture_rate)} | ${pc(c.move_capture.no_setup_or_trigger_rate)} | ${pc(c.move_capture.wrong_direction_rate)} | ${pc(c.false_move.fp_rate_24)} |`; }).join('\n')}\n\ncontrol_reproduces_v3_dev = ${R.meta.controls.control_reproduces_v3_dev}; control_reproduces_v3_hold = ${R.meta.controls.control_reproduces_v3_hold}. CONTROL direction (HOLD, independent signals): ${Object.entries(HC.diagnostics.direction).map(([k, v]) => `${k} n ${v.n} ${f(v.expectancy_r)} R`).join('; ')}. HTF context: ${Object.entries(HC.diagnostics.htf).map(([k, v]) => `${k} n ${v.n} ${f(v.expectancy_r)} R`).join('; ')}.\n`);
copyFileSync(join(ROOT, 'V4_PREREGISTRATION.md'), join(OUT, 'V4_PREREGISTRATION.md')); copyFileSync(join(ROOT, 'V4_PREREGISTRATION.sha256'), join(OUT, 'V4_PREREGISTRATION.sha256')); copyFileSync(join(ROOT, 'V4_CONTROL_BASELINE.sha256'), join(OUT, 'V4_CONTROL_BASELINE.sha256'));
W('DATA_PROVENANCE.md', `# DATA PROVENANCE\n\n| Input | Source | Size | Hash reference |\n|---|---|---|---|\n| 5m bars | handoff/edge_discovery_lab/data/XAUUSDm_bars.json (MT5 XAUUSDm, 2025-05-05 → 2026-09-30) | ${R.meta.bars} bars | results/control_inputs.sha256 |\n| Replay rows (context + CONTROL wait reasons) | handoff/edge_discovery_lab/data/lab_rows.jsonl | ${R.meta.rows} in-range rows | results/control_inputs.sha256 |\n| Production candidates (CONTROL) | research/entry_architecture_v2/results/candidates.jsonl | ${R.meta.control_signals} BUY/SELL signals | results/control_inputs.sha256 |\n| V2 / V3 results, finalists, pre-registrations | research/entry_engine_core_rebuild_v2, research/entry_edge_v3 | — | results/control_inputs.sha256 (25 lines) |\n| Re-entry guard | src/engine/capitalHarvest/positionManager.js canReenter (pure, unwired) | — | repo HEAD |\n\nSplit: DEV ${R.meta.split.dev.join(' → ')} (${R.meta.sessions_dev} sessions), HOLDOUT ${R.meta.split.hold.join(' → ')} (${R.meta.sessions_hold} sessions). Costs ${JSON.stringify(R.meta.costs)}; swap −0.56 USD per BUY night; horizon 288 bars; SL before TP; broker fail-safe 1.5 × structural + spread. RR ${R.meta.rr}; structural risk floored at ${R.meta.risk_atr[0]} ATR and rejected above ${R.meta.risk_atr[1]} ATR; ATR floor ${R.meta.atr_floor_usd} USD.\n\nAll V4 features are computed from the bar array only (plus the 30m regime label of the replay row for family G); nothing was captured live; no process was touched. Session gaps: the bar array is contiguous across gaps (as in production), the move-event window stops at a gap > 3 h.\n`);
{ const p = R.HOLD.pre_move, pd = R.DEV.pre_move; W('LARGE_MOVE_DEFINITION.md', `# LARGE MOVE DEFINITION (frozen before analysis; identical to V1–V3)\n\nOnset k = the last confirmed close before a move: from close[k], within 24 bars the favourable excursion reaches ≥ 3 × ATR14(k) before the adverse excursion reaches 1 × ATR14(k); direction = the side that qualifies first; events are non-overlapping (next scan starts at k + 24); a session gap (> 3 h) ends the window. ATR14 = simple 14-bar mean true range. Recorded per event: start k, end bar (3 ATR reached), direction, magnitude (max favourable excursion within 24 bars, USD and ATR), time-to-move.\n\n| Split | Events | BUY / SELL | Magnitude median / p90 (ATR) | Time-to-move median / p10 / p90 (bars) |\n|---|---|---|---|---|\n| DEV | ${pd.events} | ${pd.direction.BUY} / ${pd.direction.SELL} | ${f(pd.magnitude_atr.median, 2)} / ${f(pd.magnitude_atr.p90, 2)} | ${pd.time_to_move_bars.median} / ${pd.time_to_move_bars.p10} / ${pd.time_to_move_bars.p90} |\n| HOLD | ${p.events} | ${p.direction.BUY} / ${p.direction.SELL} | ${f(p.magnitude_atr.median, 2)} / ${f(p.magnitude_atr.p90, 2)} | ${p.time_to_move_bars.median} / ${p.time_to_move_bars.p10} / ${p.time_to_move_bars.p90} |\n\nValidity review: the definition is deterministic, uses forward bars only for labelling, and reproduced V3's event counts exactly (1,640 / 1,842; asserted). Known limitations (not defects): (a) the onset is the last pre-move close, so an entry at k is "at onset" and k + 1 … k + 6 is "late but inside the capture window"; (b) a 3-ATR move that needs 1–2 ATR of adverse excursion first is not an event (conservative); (c) ATR14 is a simple mean, not Wilder's. The forward label never enters a feature (prefix-invariance and leak/null controls). Sample events: ${R.DEV.events_sample ? R.DEV.events_sample.slice(0, 8).map((e) => `${new Date(e.t * 1000).toISOString().slice(0, 16)} ${e.dir} ${e.magnitude_atr} ATR in ${e.time_to_move} bars`).join('; ') : '(see v4_results_DEV_phase.json)'}.\n`); }

// ---------- PRE_MOVE_FEATURE_RESEARCH / FEATURE_ATTRIBUTION ----------
{ let md = `# PRE-MOVE FEATURE RESEARCH (information at the onset candle k and averaged over k − 6 … k − 1, versus all in-range candles; quintile lifts = pre-move share / base share)\n\nA lift of 1.0 means the feature is as common before a large move as at any other time. Lifts above ~1.3 or below ~0.75 are the only ones worth attention; everything else is noise around the base rate.\n`; for (const S of S2) { const p = R[S].pre_move; md += `\n## ${S} (${p.events} events, ${p.baseline_candles} baseline candles)\n| Feature | Base median | Pre-move median (k) | Pre-move window median (k−6…k−1) | Lift by quintile Q1 → Q5 | Median before BUY / before SELL |\n|---|---|---|---|---|---|\n`; for (const [k, v] of Object.entries(p.numeric)) md += `| ${k} | ${f(v.base_median)} | ${f(v.pre_median)} | ${f(v.pre_window_median)} | ${v.lift.map((x) => f(x, 2)).join(' / ')} | ${f(v.buy_median)} / ${f(v.sell_median)} |\n`; md += `\n| Categorical | State: base share → pre-move share (lift) |\n|---|---|\n`; for (const [k, v] of Object.entries(p.categorical)) md += `| ${k} | ${Object.entries(v).filter(([, x]) => x.base_share > 0).map(([c, x]) => `${c}: ${pc(x.base_share)} → ${pc(x.pre_share)} (${f(x.lift, 2)})`).join('; ')} |\n`; }
  const h = R.HOLD.pre_move.numeric, d = R.DEV.pre_move.numeric; md += `\n## Reading\n1. **Almost nothing precedes a large move.** Across 19 numeric and 10 categorical features, the only quintile lifts above 1.3 in BOTH splits are the size and body of the onset candle itself (bar range top quintile ${f(d.bar_range_atr.lift[4], 2)} / ${f(h.bar_range_atr.lift[4], 2)}, body ratio top quintile ${f(d.body_ratio.lift[4], 2)} / ${f(h.body_ratio.lift[4], 2)}) — i.e. the last candle before the move is already a larger, more decisive candle. The window k−6…k−1 shows no such signature (bar range window median ${f(d.bar_range_atr.pre_window_median)} vs base ${f(d.bar_range_atr.base_median)}).\n2. **Compression is a weak, not a strong, precursor.** 12-vs-previous-12 range contraction bottom quintile lift ${f(d.contraction_12_vs_prev12.lift[0], 2)} / ${f(h.contraction_12_vs_prev12.lift[0], 2)}; ATR-percentile top quintile lift ${f(d.atr_pct_288.lift[4], 2)} / ${f(h.atr_pct_288.lift[4], 2)} (high volatility makes a further 3-ATR move slightly LESS likely); the "quiet" momentum state used by family E is LESS common before moves (lift ${f(R.DEV.pre_move.categorical.setup_E_quiet.true.lift, 2)} / ${f(R.HOLD.pre_move.categorical.setup_E_quiet.true.lift, 2)}); the 12-bar range in ATR is essentially at base. Compression raises the odds of a large move by about 20–30 %, from a base of roughly one event per 28 candles.\n3. **The directional information is contrarian.** Before an UP move the previous six bars drifted DOWN (mom6 median ${f(d.mom6_atr.buy_median)} / ${f(h.mom6_atr.buy_median)} ATR) and the onset candle closed in its lower third (close location ${f(d.close_location.buy_median)} / ${f(h.close_location.buy_median)}); before a DOWN move the mirror image (mom6 ${f(d.mom6_atr.sell_median)} / ${f(h.mom6_atr.sell_median)}, close location ${f(d.close_location.sell_median)} / ${f(h.close_location.sell_median)}). Large moves begin AGAINST the short-term drift, which is why momentum/continuation triggers enter on the wrong side (V2: 88 % of opposite signals were STRUCTURE_MISREAD) and why distance-to-swing shows the move starting ~2 ATR from the swing it will break (dist to swing high before BUY ${f(h.dist_swing_high_atr.buy_median)} ATR).\n4. **Regime, bias, HTF and equal-high/low states carry no pre-move information** (all lifts 0.9–1.1 except HIGH_VOLATILITY 0.70–0.71, where moves are rarer).\n5. Consequence for setup design: a setup that is "eligible" 25–70 % of the time before a move is also eligible most of the time when no move follows; the features available at the close before a move do not separate the two populations. See FEATURE_ATTRIBUTION.md for the economic test.\n`; W('PRE_MOVE_FEATURE_RESEARCH.md', md); }
{ let md = `# FEATURE ATTRIBUTION (does a feature improve executable economics? pooled unblocked trigger signals of the seven selected grid points, grouped by the feature's quintile at the trigger bar; EXIT_F normal costs; independent signals)\n`; for (const S of S2) { md += `\n## ${S}\n| Feature | Quintile cuts | N per quintile | Expectancy (R) Q1 → Q5 | Monotonic? |\n|---|---|---|---|---|\n`; for (const [k, v] of Object.entries(R[S].feature_economics)) md += `| ${k} | ${v.cuts.map((x) => f(x, 2)).join(' / ')} | ${v.n.join(' / ')} | ${v.expectancy_r.map((x) => f(x)).join(' / ')} | ${v.monotonic} |\n`; }
  md += `\n## Family-level attribution (grid point selected on DEV; occurrence, precedes-move rate, false rate, economics)\n| Split | Candidate | Raw triggers | Blocked | Unblocked | Precedes a same-direction onset (−6…+12 bars) | False rate | FP rate (24 bars) | Independent exp (R) | Sequential N / exp / PF | Stress exp | MFE / MAE (R) |\n|---|---|---|---|---|---|---|---|---|---|---|---|\n`; for (const S of S2) for (const k of Object.keys(DEFN.finalists)) { const g = R[S].grid[DEFN.finalists[k].grid_key]; md += `| ${S} | ${SNAME[k]} | ${g.raw} | ${g.blocked} | ${g.independent.n} | ${pc(g.precedes_move_rate)} | ${pc(g.false_rate)} | ${pc(g.fp_rate_24)} | ${f(g.independent.expectancy_r)} | ${g.sequential.n} / ${f(g.sequential.expectancy_r)} / ${f(g.sequential.pf, 2)} | ${f(g.stress_expectancy_r)} | ${f(g.independent.mfe_r, 2)} / ${f(g.independent.mae_r, 2)} |\n`; }
  md += `\n## Reading\nNo pre-move feature is monotonically related to trigger economics in both splits. The two features that are monotonic on HOLD (6-bar momentum and acceleration at the trigger: higher → worse) are non-monotonic on DEV and run in the direction "fading momentum is better", consistent with the contrarian pre-move signature. Every family's triggers precede a same-direction onset 33–45 % of the time and are false 55–65 % of the time; CONTROL's own false-positive rate is ${pc(HC.false_move.fp_rate_24)}. Correlation with move onsets exists for none of the features at a level that changes executable economics; no feature was promoted to a rule.\n`; W('FEATURE_ATTRIBUTION.md', md); }

// ---------- per-family documents ----------
const FAMDOC = { A: 'COMPRESSION_EXPANSION.md', B: 'SWEEP_RECLAIM.md', C: 'STRUCTURE_BREAK_CONFIRMATION.md', D: 'PULLBACK_CONTINUATION.md', E: 'MOMENTUM_IGNITION.md', F: 'RANGE_ACCEPTANCE.md', G: 'TREND_RESUMPTION.md' };
const FAMREAD = {
  A: (S1d, S1h) => `The compression → expansion family was the only DEV-supported family (${S1d.definition.grid_key}: DEV n ${S1d.n}, ${f(S1d.expectancy_r)} R, PF ${f(S1d.pf, 2)}, stress ${f(S1d.stress.expectancy_r)}, BUY ${f(R.DEV.candidates.S1.diagnostics.direction.BUY?.expectancy_r)} R / SELL ${f(R.DEV.candidates.S1.diagnostics.direction.SELL?.expectancy_r)} R) and it reversed on HOLDOUT (n ${S1h.n}, ${f(S1h.expectancy_r)} R, PF ${f(S1h.pf, 2)}; BUY ${f(S1h.diagnostics.direction.BUY?.expectancy_r)} R / SELL ${f(S1h.diagnostics.direction.SELL?.expectancy_r)} R — the DEV BUY edge became the HOLD loser). All three thresholds were ROBUST on DEV and NEGATIVE_CENTRE on HOLD. Half of the raw triggers are blocked because the compression range plus the expansion bar puts the structural stop beyond 3 ATR (RISK ${S1h.diagnostics.blocked.RISK ?? 0} of ${S1h.diagnostics.raw_signals}). A compression setup existed at or before onset for ${pc(S1h.forensics.earliest_setup_rel_onset.at_or_before_onset)} of HOLD moves, but the expansion trigger fired at or before onset for only ${pc(S1h.forensics.earliest_trigger_rel_onset.at_or_before_onset)}: the setup is common, the confirming bar IS the move. A1 (range break only) and A3 (directional bar only) were worse on DEV. Verdict: NOT SUPPORTED out of sample; DEV result was a 114-trade artefact.`,
  B: (d, h) => `Sweep → reclaim (B2, confirmation close within 6 bars) is the highest-frequency family (HOLD ${h.signals} unblocked signals, ${h.n} trades, ${f(h.trades_per_session?.median)} per session) and captures ${pc(h.move_capture.capture_rate)} of HOLD moves (CONTROL ${pc(HC.move_capture.capture_rate)}), but at ${f(h.expectancy_r)} R (PF ${f(h.pf, 2)}, DD ${f(h.max_dd_r, 1)} R); DEV ${f(d.expectancy_r)} R. ${pc(h.false_move.false_rate)} of its signals are not followed by a move; ${h.false_move.labels.FAILED_RECLAIM ?? 0} of the ${h.false_move.false} false signals fail by price trading back through the sweep extreme. The sweep bar itself (B1) is far worse (DEV −0.15 R, n 1,658). Direction: HOLD SELL ${f(h.diagnostics.direction.SELL?.expectancy_r)} R vs BUY ${f(h.diagnostics.direction.BUY?.expectancy_r)} R — asymmetric, but DEV showed BUY ≈ SELL, so no directional rule is supportable. Verdict: sweeps are everywhere (3/3 pivots are swept constantly); the reclaim carries no edge, matching V2's NT2 result.`,
  C: (d, h) => `First structure break (C1) is the best detector in the study: setup (price within 1 ATR of the swing) exists before ${pc(h.forensics.earliest_setup_rel_onset.at_or_before_onset)} of HOLD moves, the trigger fires inside the capture window for ${pc(h.move_capture.capture_rate)} of moves (CONTROL ${pc(HC.move_capture.capture_rate)}) and NO_SETUP + SETUP_NO_TRIGGER falls to ${pc(h.forensics.rates.NO_SETUP + h.forensics.rates.SETUP_NO_TRIGGER)} (CONTROL ${pc(HC.move_capture.no_setup_or_trigger_rate)}). It is also wrong-direction on ${pc(h.forensics.rates.WRONG_DIRECTION)} of events and ALREADY_POSITIONED on ${pc(h.forensics.rates.ALREADY_POSITIONED)} (it is in a trade from a previous break when the real move starts). Economics: HOLD ${f(h.expectancy_r)} R, PF ${f(h.pf, 2)} (DEV ${f(d.expectancy_r)} R); ${pc(h.false_move.false_rate)} of breaks are false, ${h.false_move.labels.FAILED_BREAKOUT ?? 0} of them re-close inside within 12 bars. Waiting for confirmation (C2 second close, C3 retest) did not help: DEV C2 −0.053 R, C3 −0.066/−0.091 R — confirmation removes trades and adds displacement without changing the win rate. ${h.diagnostics.blocked.RISK ?? 0} of ${h.diagnostics.raw_signals} raw breaks were blocked because the structural stop (last swing) is > 3 ATR away. Verdict: detection improved, economics not — the break is the first visible evidence of the move and also the first visible evidence of every failed move.`,
  D: (d, h) => `Pullback → continuation (D1 continuation candle) is the worst family: HOLD ${f(h.expectancy_r)} R, PF ${f(h.pf, 2)}, DD ${f(h.max_dd_r, 1)} R, CI ${ci(h.ci95_r)} (entirely below zero); DEV ${f(d.expectancy_r)} R. Both sides lose (BUY ${f(h.diagnostics.direction.BUY?.expectancy_r)}, SELL ${f(h.diagnostics.direction.SELL?.expectancy_r)}), every regime loses, HTF-aligned loses less (${f(h.diagnostics.htf.ALIGNED?.expectancy_r)} R) but still loses. The two-close variant (D2) is equally negative. Pullback depth (0.8 vs 1.2 ATR) does not matter — once a pullback has touched EMA20 from a 20-bar extreme it is almost always deeper than 1.2 ATR. This confirms V1–V3: PB's apparent HOLD strength was a regime slice, not a continuation edge. Verdict: REJECTED.`,
  E: (d, h) => `Momentum ignition almost never qualifies: of ${h.diagnostics.raw_signals} raw ignition bars on HOLD, ${h.diagnostics.blocked.LATE_EXHAUSTION ?? 0} are already > 2 ATR from the 12-bar origin (LATE_EXHAUSTION) and only ${h.signals} trade (${f(h.expectancy_r)} R). A 1-ATR three-bar thrust from a quiet state is, by the time it closes, usually the move's second or third ATR. This is the same finding as V2's NT3 (5–13 entries). Separating early ignition from late exhaustion is possible mechanically but leaves no population to trade. Verdict: NOT TESTABLE AT USEFUL N; the "quiet" precondition is itself anti-predictive (pre-move lift 0.75–0.86).`,
  F: (d, h) => `Range break → acceptance: a 36-bar range ≤ 4 ATR occurs before only ${pc(h.forensics.earliest_setup_rel_onset.at_or_before_onset)} of HOLD moves (NO_SETUP ${pc(h.forensics.rates.NO_SETUP)}); the first close outside (F1) earns ${f(h.expectancy_r)} R on HOLD (DEV ${f(d.expectancy_r)} R), the two-close acceptance (F2) is worse on both splits, and ${h.false_move.labels.RANGE_REENTRY ?? 0} of ${h.false_move.false} false breaks re-enter the range within 12 bars. Acceptance measured at entry time (second close) does not distinguish continuation from failure. Verdict: REJECTED.`,
  G: (d, h) => `Trend resumption (EMA50 trend + 30m trend regime + pullback to EMA20 + momentum recovery, chase guard 1.5 ATR) is the only family positive on both splits (DEV n ${d.n}, ${f(d.expectancy_r)} R; HOLD n ${h.n}, ${f(h.expectancy_r)} R, PF ${f(h.pf, 2)}, CI ${ci(h.ci95_r)}) but it fires ${h.signals} times in nine months (${pc(h.zero_trade_session_rate)} of sessions empty), captures ${pc(h.move_capture.capture_rate)} of moves, and ${h.diagnostics.blocked.RISK ?? 0} + ${h.diagnostics.blocked.CHASE ?? 0} of ${h.diagnostics.raw_signals} raw triggers are blocked (stop > 3 ATR or displacement > 1.5 ATR). Its HOLD net R depends on an 18-trade BEAR_TREND SELL cell (tiny-cell share ${pc(h.tiny_cells?.max_tiny_cell_share)}). Verdict: INSUFFICIENT — a plausible, slow, low-frequency pattern whose evidence (73 trades in 16 months) cannot support a decision; it is the only V4 lead worth a longer forward sample, and it is not an answer to the detection problem.`,
};
for (const [fam, file] of Object.entries(FAMDOC)) { const name = `S${'ABCDEFG'.indexOf(fam) + 1}`; const fin = DEFN.finalists[name]; let md = `# ${FAMNAME[fam]} (family ${fam}; candidate ${name})\n\nFrozen definition: see V4_PREREGISTRATION.md §5. Grid point selected on DEV: **${fin.grid_key}** (${fin.supported ? 'DEV-SUPPORTED' : 'UNSUPPORTED on DEV, carried once to HOLDOUT as pre-registered'}${fin.note ? '; ' + fin.note : ''}).\n\n## Grid (sequential one-position, EXIT_F normal costs; independent-signal expectancy in brackets)\n| Grid point | Split | Raw | Blocked | Independent N (exp R) | Sequential N | Exp (R) | PF | DD (R) | 95 % CI | Stress | BUY n / exp | SELL n / exp | Precedes move | False rate | Capture |\n|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|\n`; for (const g of R.meta.grid.filter((k) => R.DEV.grid[k].fam === fam)) for (const S of S2) { const v = R[S].grid[g]; md += `| ${g} | ${S} | ${v.raw} | ${v.blocked} | ${v.independent.n} (${f(v.independent.expectancy_r)}) | ${v.sequential.n} | ${f(v.sequential.expectancy_r)} | ${f(v.sequential.pf, 2)} | ${f(v.sequential.max_dd_r, 1)} | ${ci(v.sequential.ci95_r)} | ${f(v.stress_expectancy_r)} | ${v.buy.n} / ${f(v.buy.expectancy_r)} | ${v.sell.n} / ${f(v.sell.expectancy_r)} | ${pc(v.precedes_move_rate)} | ${pc(v.false_rate)} | ${pc(v.capture)} |\n`; }
  const d = R.DEV.candidates[name], h = R.HOLD.candidates[name]; md += `\n## Selected candidate ${name}\n| Split | Trades | Exp (R) | PF | DD (R) | 95 % CI | Stress | Quarters > 0 | Capture | NO_SETUP | SETUP_NO_TRIGGER | TRIGGER_BLOCKED | WRONG_DIRECTION | Earliest setup ≤ onset | Earliest trigger ≤ onset | False rate | Exit mix |\n|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|\n${S2.map((S) => { const v = R[S].candidates[name]; return `| ${S} | ${v.n} | ${f(v.expectancy_r)} | ${f(v.pf, 2)} | ${f(v.max_dd_r, 1)} | ${ci(v.ci95_r)} | ${f(v.stress.expectancy_r)} | ${pc(v.quarters_positive_share)} | ${pc(v.move_capture.capture_rate)} | ${pc(v.forensics.rates.NO_SETUP)} | ${pc(v.forensics.rates.SETUP_NO_TRIGGER)} | ${pc(v.forensics.rates.TRIGGER_BLOCKED)} | ${pc(v.forensics.rates.WRONG_DIRECTION)} | ${pc(v.forensics.earliest_setup_rel_onset.at_or_before_onset)} | ${pc(v.forensics.earliest_trigger_rel_onset.at_or_before_onset)} | ${pc(v.false_move.false_rate)} | ${Object.entries(v.exit_mix).map(([a, b]) => `${a} ${pc(b)}`).join(', ')} |`; }).join('\n')}\n\nTiming classes (HOLD, displacement from the 12-bar origin): ${Object.entries(h.diagnostics.timing).map(([k, v]) => `${k} n ${v.n} ${f(v.expectancy_r)} R (MAE3 ${f(v.mae3_r, 2)})`).join('; ')}. Direction (HOLD): ${Object.entries(h.diagnostics.direction).map(([k, v]) => `${k} n ${v.n} ${f(v.expectancy_r)} R`).join('; ')}. Regime (HOLD): ${Object.entries(h.diagnostics.regime).map(([k, v]) => `${k} n ${v.n} ${f(v.expectancy_r)}`).join('; ')}. HTF (HOLD): ${Object.entries(h.diagnostics.htf).map(([k, v]) => `${k} n ${v.n} ${f(v.expectancy_r)}`).join('; ')}. False-move labels (HOLD): ${Object.entries(h.false_move.labels).map(([k, v]) => `${k} ${v}`).join(', ')}; false signals earn ${f(h.false_move.false_expectancy_r)} R, followed signals ${f(h.false_move.followed_expectancy_r)} R.\n\n## Verdict\n${FAMREAD[fam](d, h)}\n`; W(file, md); }

// ---------- architecture / timing / location / direction / regime / HTF ----------
W('SETUP_TRIGGER_ARCHITECTURE.md', `# SETUP / TRIGGER ARCHITECTURE (what V4 built, and what the production engine does)\n\n## Production engine (src/engine/intraday/models5m.js, read for this stage)\nOne candidate per confirmed 5m bar, priority MC > PB > BO > SR > MR, every model gated by the 15m bias and its eligible-model list. Setups/triggers: MC = 3 progressing closes on the bias side of EMA20 with ATR ratio ≥ 1.0 and a confirmed close beyond the prior 5m swing within 3 bars; PB = a ≥ 1.0 ATR correction against the 15m bias RESOLVED by 2 closes back on the bias side of EMA20, within 3 bars; BO = structure event (BOS/CHoCH) + retest within 0.3 ATR + reclaim within 10 bars; SR = rejection wick ≥ 50 % at a 5m/15m swing with close in the outer third (counter-structure needs a fresh sweep or supporting bias); MR = fresh 5m sweep + reclaim at a 15m range boundary in a 15m RANGE. Then risk5m (structural stop, min 0.5 ATR, objective ≥ 1.0 R, minRR 1.70), overextension 2.5 ATR, quality 65/70 with 1H penalty, MTF vetoes. Every production trigger therefore REQUIRES prior structure (a swing break, a resolved pullback, a retest, a rejection wick, a sweep) — which, per PRE_MOVE_FEATURE_RESEARCH.md and V2's diagnosis, is absent before ~78 % of large moves.\n\n## V4 architecture (strict separation, deterministic, no composite score)\n| Family | SETUP (eligibility, holds at t − 1) | TRIGGER (specific event at t) | Invalidation (stop) | Chase / block rules |\n|---|---|---|---|---|\n| A | 12-bar range ≤ wA ATR and ATR percentile ≤ 0.5 | expansion bar ≥ xA ATR closing beyond the range (A1), + beyond the swing (A2), or directional only (A3) | opposite end of the compression range | stop > 3 ATR → RISK; ATR < 2 USD |\n| B | a sweep of a ≥ 6-bar-old confirmed swing within aB bars | sweep bar (B1) or first close beyond the sweep bar's opposite extreme (B2) | sweep extreme + 0.1 ATR | close > 1.5 ATR from the level → CHASE |\n| C | price within 1 ATR of the confirmed swing | first close beyond (C1), second close (C2), retest within rC bars (C3) | last confirmed opposite swing | break close > 1.5 ATR from level → CHASE; stop > 3 ATR → RISK |\n| D | EMA20 > EMA50, EMA50 rising 12 bars, pullback ≥ dD ATR to EMA20 ± 0.3 ATR, swing intact | continuation candle (D1) or two closes back above EMA20 (D2) | pullback low | within 3 bars of the pullback low |\n| E | quiet: abs(mom6) ≤ 0.5 ATR and 12-bar range ≤ 3 ATR at t − 3 | mom3 ≥ mE ATR, acceleration > 0, body ≥ 0.6, close location ≥ 0.75 | lowest low of the last 3 bars | displacement from the 12-bar origin > 2 ATR → LATE_EXHAUSTION |\n| F | 36-bar range ≤ wF ATR | first close outside with close location ≥ 0.6 (F1) or second consecutive close outside (F2) | boundary − 0.5 ATR | re-entry before F2 = rejection, no trade |\n| G | EMA50 rising 24 bars, close > EMA50, 30m regime trend, pullback to EMA20 ± 0.3 ATR without a close below EMA50, swing intact | mom3 ≥ 0.5 ATR and close > previous high | pullback low | displacement from the pullback low > dG ATR → CHASE |\nCommon: entry = close of the trigger bar; TP = entry ± 1.70 × risk; risk floored at 0.5 ATR; EXIT_F; one position; production re-entry guard; ATR ≥ 2 USD. BUY/SELL mirrored. Regime and HTF are context diagnostics, not gates (G's 30m trend is part of its pre-registered setup).\n\n## What the architecture showed\nSetup states are common (A present before ${pc(R.HOLD.candidates.S1.forensics.earliest_setup_rel_onset.at_or_before_onset)} of HOLD moves, C ${pc(R.HOLD.candidates.S3.forensics.earliest_setup_rel_onset.at_or_before_onset)}, B ${pc(R.HOLD.candidates.S2.forensics.earliest_setup_rel_onset.at_or_before_onset)}) and triggers are rare or late (A trigger ≤ onset ${pc(R.HOLD.candidates.S1.forensics.earliest_trigger_rel_onset.at_or_before_onset)}, C ${pc(R.HOLD.candidates.S3.forensics.earliest_trigger_rel_onset.at_or_before_onset)}, median trigger 1–4 bars before onset where it exists). The confirming event that answers "why now?" is, in XAUUSD 5m data, the first bar of the move itself; everything earlier is indistinguishable from the base rate. See CANDIDATE_DEFINITIONS.md and ENTRY_CORE_V4_SPEC.md.\n`);
{ let md = `# TRIGGER TIMING (displacement from the move origin = 12-bar extreme at the trigger: EARLY < 0.3 ATR, VALID 0.3–1.5 ATR, LATE/CHASED > 1.5 ATR; bars since setup formation; MAE within 3 bars)\n`; for (const S of S2) { md += `\n## ${S}\n| Candidate | Class | N | Win | Exp (R) | PF | MAE3 (R) | MFE (R) |\n|---|---|---|---|---|---|---|---|\n`; for (const k of CANDS) for (const [c, v] of Object.entries(R[S].candidates[k].diagnostics.timing)) md += `| ${SNAME[k]} | ${c} | ${v.n} | ${pc(v.win_rate)} | ${f(v.expectancy_r)} | ${f(v.pf, 2)} | ${f(v.mae3_r, 2)} | ${f(v.mfe_r, 2)} |\n`; md += `\n| Candidate | Setup age terciles (bars) | LOW n / exp | MID n / exp | HIGH n / exp |\n|---|---|---|---|---|\n`; for (const k of CANDS) { const t = R[S].candidates[k].diagnostics.timing_setup_age; md += t ? `| ${SNAME[k]} | ${t.cuts.join(' / ')} | ${t.LOW.n} / ${f(t.LOW.expectancy_r)} | ${t.MID.n} / ${f(t.MID.expectancy_r)} | ${t.HIGH.n} / ${f(t.HIGH.expectancy_r)} |\n` : `| ${SNAME[k]} | — | — | — | — |\n`; } }
  md += `\n## Reading\nBy construction every confirmation trigger is LATE relative to the 12-bar origin: the expansion bar, the break bar and the continuation bar close 1.5–3 ATR away from where the move started (A/C/F 100 % LATE_CHASED). The two families with "VALID" entries (B2 reclaim, D1 continuation) earn LESS in the VALID class than in the LATE class on HOLD (B2 VALID ${f(R.HOLD.candidates.S2.diagnostics.timing.VALID?.expectancy_r)} vs LATE ${f(R.HOLD.candidates.S2.diagnostics.timing.LATE_CHASED?.expectancy_r)} R; D1 VALID ${f(R.HOLD.candidates.S4.diagnostics.timing.VALID?.expectancy_r)} vs LATE ${f(R.HOLD.candidates.S4.diagnostics.timing.LATE_CHASED?.expectancy_r)} R) with larger MAE within 3 bars — entering earlier means more adverse excursion, not more edge. "Early enough + confirmed enough" is not available: the earliest confirmable event is the move's first bar.\n`; W('TRIGGER_TIMING.md', md); }
{ let md = `# ENTRY LOCATION (terciles of structural risk, displacement from origin, distance to confirmed swings in ATR at the trigger; independent unblocked signals)\n`; for (const S of S2) { md += `\n## ${S}\n| Candidate | Feature | Cuts | LOW n / exp | MID n / exp | HIGH n / exp |\n|---|---|---|---|---|---|\n`; for (const k of CANDS) for (const [fe, v] of Object.entries(R[S].candidates[k].diagnostics.location)) md += v ? `| ${SNAME[k]} | ${fe} | ${v.cuts.map((x) => f(x, 2)).join(' / ')} | ${v.LOW.n} / ${f(v.LOW.expectancy_r)} | ${v.MID.n} / ${f(v.MID.expectancy_r)} | ${v.HIGH.n} / ${f(v.HIGH.expectancy_r)} |\n` : `| ${SNAME[k]} | ${fe} | — | — | — | — |\n`; }
  md += `\n## Reading\nAs in V1–V3, wider structural stops earn more than tight ones (S3 risk LOW ${f(R.HOLD.candidates.S3.diagnostics.location.risk_atr?.LOW.expectancy_r)} vs HIGH ${f(R.HOLD.candidates.S3.diagnostics.location.risk_atr?.HIGH.expectancy_r)} R on HOLD) because tight stops are hit by noise; no tercile of any location feature is positive with a CI above zero. Entry location does not rescue a trigger that has no directional edge.\n`; W('ENTRY_LOCATION.md', md); }
W('DIRECTIONAL_ANALYSIS.md', `# DIRECTIONAL ANALYSIS (BUY and SELL evaluated independently; no side was dropped — pre-registered)\n\n| Split | Candidate | BUY n / exp (R) / PF | SELL n / exp (R) / PF | Asymmetry (BUY − SELL, R) |\n|---|---|---|---|---|\n${S2.flatMap((S) => ['CONTROL', ...CANDS].map((k) => { const v = k === 'CONTROL' ? R[S].control : R[S].candidates[k]; const b = v.diagnostics.direction.BUY ?? { n: 0 }, s = v.diagnostics.direction.SELL ?? { n: 0 }; return `| ${S} | ${k === 'CONTROL' ? 'CONTROL' : SNAME[k]} | ${b.n} / ${f(b.expectancy_r)} / ${f(b.pf, 2)} | ${s.n} / ${f(s.expectancy_r)} / ${f(s.pf, 2)} | ${b.expectancy_r != null && s.expectancy_r != null ? f(b.expectancy_r - s.expectancy_r) : '—'} |`; })).join('\n')}\n\n## Reading\nAsymmetry exists but does not persist: S1 (compression → expansion) was BUY +0.46 / SELL −0.04 R on DEV and BUY ${f(R.HOLD.candidates.S1.diagnostics.direction.BUY?.expectancy_r)} / SELL ${f(R.HOLD.candidates.S1.diagnostics.direction.SELL?.expectancy_r)} R on HOLD (sign flip on both sides); S2 and S3 are SELL-favoured on HOLD (+0.08 / +0.06 R) but were not on DEV. CONTROL itself is SELL ${f(HC.diagnostics.direction.SELL?.expectancy_r)} / BUY ${f(HC.diagnostics.direction.BUY?.expectancy_r)} R on HOLD. The pre-move research shows the structural reason: moves begin against the short-term drift in both directions, so any directional rule learnt on one year inverts on the next. No directional rule survives chronological holdout; none was encoded.\n`);
W('REGIME_CONTEXT.md', `# REGIME CONTEXT (production 5m regime at the trigger, as context only; independent unblocked signals)\n\n${S2.map((S) => `## ${S}\n| Candidate | ${['COMPRESSION', 'BEAR_TREND', 'BULL_TREND', 'TRANSITION', 'RANGE', 'HIGH_VOLATILITY'].join(' | ')} |\n|---|---|---|---|---|---|---|\n${['CONTROL', ...CANDS].map((k) => { const v = k === 'CONTROL' ? R[S].control : R[S].candidates[k]; return `| ${k === 'CONTROL' ? 'CONTROL' : SNAME[k]} | ${['COMPRESSION', 'BEAR_TREND', 'BULL_TREND', 'TRANSITION', 'RANGE', 'HIGH_VOLATILITY'].map((rg) => { const c = v.diagnostics.regime[rg]; return c ? `n ${c.n}, ${f(c.expectancy_r)}` : '—'; }).join(' | ')} |`; }).join('\n')}\n`).join('\n')}\n## Reading\nNo family works across regimes and no family works in one regime on both splits: S3 (first break) is +0.17 R in BEAR_TREND and +0.16 R in RANGE on HOLD but −0.21 R in TRANSITION; on DEV the signs differ. Pre-move research shows regime carries no information about where moves begin (lifts 0.9–1.1; COMPRESSION 1.04–1.09). Regime was therefore not forced into any candidate, and no regime-specific eligibility is supportable from this data — the same conclusion as V3's REGIME_DIRECTION_MATRIX.\n`);
W('HTF_CONTEXT.md', `# HTF CONTEXT (30m and 1H regime at the confirmed 5m close: ALIGNED = both trend labels agree with the side, CONFLICTING = both oppose, NEUTRAL = no trend label, MIXED = one each; context only, never a gate)\n\n${S2.map((S) => `## ${S}\n| Candidate | ALIGNED n / exp | NEUTRAL n / exp | CONFLICTING n / exp | MIXED n / exp |\n|---|---|---|---|---|\n${['CONTROL', ...CANDS].map((k) => { const v = k === 'CONTROL' ? R[S].control : R[S].candidates[k]; const g = v.diagnostics.htf; const c = (x) => (g[x] ? `${g[x].n} / ${f(g[x].expectancy_r)}` : '—'); return `| ${k === 'CONTROL' ? 'CONTROL' : SNAME[k]} | ${c('ALIGNED')} | ${c('NEUTRAL')} | ${c('CONFLICTING')} | ${c('MIXED')} |`; }).join('\n')}\n`).join('\n')}\n## Reading\nHTF alignment does not improve precision, expectancy or drawdown in any family: for S3 HOLD ALIGNED ${f(R.HOLD.candidates.S3.diagnostics.htf.ALIGNED?.expectancy_r)} R vs NEUTRAL ${f(R.HOLD.candidates.S3.diagnostics.htf.NEUTRAL?.expectancy_r)} R vs CONFLICTING ${f(R.HOLD.candidates.S3.diagnostics.htf.CONFLICTING?.expectancy_r)} R; for CONTROL ALIGNED ${f(HC.diagnostics.htf.ALIGNED?.expectancy_r)} R vs NEUTRAL ${f(HC.diagnostics.htf.NEUTRAL?.expectancy_r)} R (aligned is WORSE, as V1's gate ablation found for the 1H veto). An HTF filter would only reduce trade count; it was not kept.\n`);

// ---------- forensics ----------
{ let md = `# MISSED-MOVE FORENSICS (every objective move event classified under each candidate; categories partition the events; "earliest detectable" = first bar in [k − 12, k + 6] with the candidate's setup state / trigger in the move direction, without hindsight)\n`; for (const S of S2) { md += `\n## ${S} (${R.meta.events[S]} events)\n${FORH}\n${ctlForRow(S)}\n${CANDS.map((k) => forRow(S, k)).join('\n')}\n`; }
  const s3 = R.HOLD.candidates.S3, s2 = R.HOLD.candidates.S2, s1 = R.HOLD.candidates.S1; md += `\n## Reading\n- **Earliest detectable point.** Where a setup state exists at all, it appears a median of 7–9 bars before onset (it is a standing condition, not an alert); where a trigger exists it fires a median 1–4 bars before onset — but "trigger before onset" is mostly a trigger on a DIFFERENT, earlier impulse in the same direction (the capture window is ± 6 bars), not anticipation. The first-break family (S3) is the only one that makes the setup + trigger problem smaller than CONTROL's (NO_SETUP + SETUP_NO_TRIGGER ${pc(s3.forensics.rates.NO_SETUP + s3.forensics.rates.SETUP_NO_TRIGGER)} vs CONTROL ${pc(HC.move_capture.no_setup_or_trigger_rate)} on HOLD) and it pays for that with WRONG_DIRECTION ${pc(s3.forensics.rates.WRONG_DIRECTION)} and ALREADY_POSITIONED ${pc(s3.forensics.rates.ALREADY_POSITIONED)} — it is usually already in a losing trade from the previous break when the real move begins.\n- **Compression (S1) and range (S6) setups miss most moves outright** (NO_SETUP ${pc(s1.forensics.rates.NO_SETUP)} and ${pc(R.HOLD.candidates.S6.forensics.rates.NO_SETUP)}): most large moves do not start from a narrow range. When the setup exists, the trigger (the expansion bar) is the move (SETUP_NO_TRIGGER ${pc(s1.forensics.rates.SETUP_NO_TRIGGER)}).\n- **Sweep (S2) captures ${pc(s2.move_capture.capture_rate)}** but the same mechanism fires ${s2.signals} times in nine months with ${pc(s2.false_move.false_rate)} false.\n- **TRIGGER_BLOCKED** is dominated by RISK (structural stop > 3 ATR) for A/C and by CHASE for B/G: the structural invalidation of a confirmed event is typically 2–4 ATR away, which is also why production's RR ≥ 1.70 gate rejects a third of its candidates. SAFETY_BLOCK is 0 in the replay (news/spread/drift are outside it and identical for every candidate).\n- **Conclusion:** the earliest point at which a valid opportunity is detectable without hindsight is the first bar of the move. Detecting it earlier would require information that, per PRE_MOVE_FEATURE_RESEARCH.md, is not in the 5m/15m/30m/1H price series.\n`; W('MISSED_MOVE_FORENSICS.md', md); }
{ let md = `# FALSE-MOVE FORENSICS (unblocked signals NOT followed by a same-direction move onset within −6 … +12 bars; failure label from the following 12 bars — labelling only)\n\n| Split | Candidate | Signals | Followed | False | False rate | FP rate (24 bars) | Followed exp (R) | False exp (R) | Failure labels |\n|---|---|---|---|---|---|---|---|---|---|\n${S2.flatMap((S) => CANDS.map((k) => { const v = R[S].candidates[k].false_move; return `| ${S} | ${SNAME[k]} | ${v.signals} | ${v.followed} | ${v.false} | ${pc(v.false_rate)} | ${pc(v.fp_rate_24)} | ${f(v.followed_expectancy_r)} | ${f(v.false_expectancy_r)} | ${Object.entries(v.labels).map(([a, b]) => `${a} ${b}`).join(', ')} |`; })).join('\n')}\n| HOLD | CONTROL | ${HC.false_move.signals} | — | — | — | ${pc(HC.false_move.fp_rate_24)} | — | — | — |\n| DEV | CONTROL | ${DC.false_move.signals} | — | — | — | ${pc(DC.false_move.fp_rate_24)} | — | — | — |\n\n## Reading\nEvery family is false 55–65 % of the time and its false signals lose 0.3–0.5 R each, while followed signals earn +0.5 to +0.7 R — the economics are entirely decided by the ratio, and no setup definition moved the ratio away from the base rate (CONTROL's own 24-bar FP rate is ${pc(HC.false_move.fp_rate_24)}). Failure modes are the mirror of the setup: false expansion (price back inside the compression range), failed reclaim (through the sweep extreme), failed breakout (close back inside), continuation failure (close below the pullback low), range re-entry. None of these is visible at the trigger bar; they are visible 2–8 bars later, when the structural stop has usually already been hit. A system that accepted every false signal to capture more moves (S2, S3) loses money; one that filtered them (S1, S7) captures 0.6–3 % of moves.\n`; W('FALSE_MOVE_FORENSICS.md', md); }

// ---------- candidates / results ----------
W('CANDIDATE_DEFINITIONS.md', `# CANDIDATE DEFINITIONS (frozen in V4_PREREGISTRATION.md §5–§6; grid point per family chosen on DEV by §8; implemented in scripts/v4_study.mjs)\n\n| Candidate | Family | Grid point | Parameters | DEV N | DEV exp (R) | DEV PF | DEV stress | DEV-supported |\n|---|---|---|---|---|---|---|---|---|\n${Object.entries(DEFN.finalists).map(([k, v]) => `| ${k} | ${v.family} — ${FAMNAME[v.family]} | ${v.grid_key} | ${JSON.stringify(v.params)} | ${v.dev_n} | ${f(v.dev_expectancy_r)} | ${f(v.dev_pf, 2)} | ${f(v.dev_stress_r)} | ${v.supported ? 'YES' : 'NO'}${v.note ? ' (' + v.note + ')' : ''} |`).join('\n')}\n\nCombinations (tested only if both components are DEV-supported): ${Object.entries(DEFN.combinations).map(([k, v]) => `${k}: ${v.tested ? (v.kept ? 'KEPT' : 'not kept') : 'not tested — ' + v.reason}`).join('; ')}. Candidate set carried to HOLDOUT: ${CANDS.join(', ')} (+ CONTROL).\n\nAll candidates share: entry = close of the trigger bar, structural stop (floored 0.5 ATR, rejected > 3 ATR), TP = entry ± 1.70 × risk, ATR ≥ 2 USD, EXIT_F, one position with the production re-entry guard, no quality score, no regime/HTF gate (G's 30m trend context is part of its definition), BUY/SELL mirrored.\n`);
W('FROZEN_FINALISTS.md', `# FROZEN FINALISTS\n\n\`configs/finalists.json\` sha256 **${R.finalists_sha256}**, derived from DEV only (results/dev_phase_console.txt), frozen before HOLDOUT was opened (results/full_phase_console.txt). Selection rule: highest DEV sequential expectancy among the family's grid points with N ≥ 80 (else the largest-N point, UNSUPPORTED). Only S1 (compression → expansion with structure break) was DEV-supported; S7 (trend resumption) was positive but n 27; the other five were negative on DEV and carried to HOLDOUT once, as pre-registered. No combination qualified for testing (every pre-registered pair has an UNSUPPORTED component).\n\n| Candidate | Grid point | DEV N | DEV exp (R) | DEV PF | Supported |\n|---|---|---|---|---|---|\n${Object.entries(DEFN.finalists).map(([k, v]) => `| ${k} | ${v.grid_key} | ${v.dev_n} | ${f(v.dev_expectancy_r)} | ${f(v.dev_pf, 2)} | ${v.supported ? 'YES' : 'no'} |`).join('\n')}\n`);
W('DEVELOPMENT_RESULTS.md', `# DEVELOPMENT RESULTS (2025-05-07 → 2025-12-31, ${R.meta.sessions_dev} sessions; EXIT_F; sequential one-position; normal costs)\n\n${finTable('DEV')}\n\n## Move-event forensics (DEV)\n${FORH}\n${ctlForRow('DEV')}\n${CANDS.map((k) => forRow('DEV', k)).join('\n')}\n\nOnly S1 (+0.23 R, n 114, BUY-driven) and S7 (+0.55 R, n 27) were positive on DEV. The first-break family (S3) already showed the pattern that HOLDOUT confirmed: best detection (capture ${pc(R.DEV.candidates.S3.move_capture.capture_rate)}), negative economics (${f(R.DEV.candidates.S3.expectancy_r)} R).\n`);
W('HOLDOUT_RESULTS.md', `# HOLDOUT RESULTS (2026-01-01 → 2026-09-29, ${R.meta.sessions_hold} sessions; opened once after configs/finalists.json was hashed; EXIT_F; sequential; normal costs)\n\n${finTable('HOLD')}\n\n## Move-event forensics (HOLD)\n${FORH}\n${ctlForRow('HOLD')}\n${CANDS.map((k) => forRow('HOLD', k)).join('\n')}\n\n## Gate decisions (V4_PREREGISTRATION.md §9)\n| Candidate | Status | Detection (14) met | Failed items |\n|---|---|---|---|\n${CANDS.map((k) => `| ${SNAME[k]} | ${DEC.candidates[k].status} | ${DEC.candidates[k].detection_met ? 'YES' : 'no'} | ${DEC.candidates[k].reasons.join('; ') || '—'} |`).join('\n')}\n\nPassing candidates: ${DEC.passing.length ? DEC.passing.join(', ') : 'none'}. Best candidate (highest HOLD expectancy with N ≥ 200): **${BEST}** (${f(HB.expectancy_r)} R, PF ${f(HB.pf, 2)}, DD ${f(HB.max_dd_r, 2)} R, CI ${ci(HB.ci95_r)}, capture ${pc(HB.move_capture.capture_rate)}, DEV ${f(DB.expectancy_r)} R). EDGE_DEMONSTRATED = ${DEC.edge_demonstrated}; V4_BEATS_CONTROL = ${DEC.v4_beats_control} (point estimate ${f(HB.expectancy_r)} vs CONTROL ${f(HC.expectancy_r)} R, CI spans zero; detection met); DEMO_ELIGIBLE = ${DEC.demo_eligible}.\n\nExit mix: ${['CONTROL', ...CANDS].map((k) => `${k} ${JSON.stringify((k === 'CONTROL' ? HC : R.HOLD.candidates[k]).exit_mix)}`).join('; ')}.\n`);
W('NORMAL_COST_RESULTS.md', `# NORMAL COST RESULTS (spread 0.24 + slippage 0.10 USD; swap −0.56 per BUY night; DRIFT = next-open fill)\n\n| Split | Candidate | Trades | Exp (R) | Exp (USD @0.01) | Gross exp (USD) | Cost USD/trade | Cost share of gross | Drift exp (R) | Drift PF |\n|---|---|---|---|---|---|---|---|---|---|\n${S2.flatMap((S) => ['CONTROL', ...CANDS].map((k) => { const v = k === 'CONTROL' ? R[S].control : R[S].candidates[k]; return `| ${S} | ${k === 'CONTROL' ? 'CONTROL' : SNAME[k]} | ${v.n} | ${f(v.expectancy_r)} | ${f(v.expectancy_usd, 2)} | ${f(v.gross_expectancy_usd, 2)} | ${f(v.cost_usd, 2)} | ${pc(v.cost_pct_gross)} | ${f(v.drift.expectancy_r)} | ${f(v.drift.pf, 2)} |`; })).join('\n')}\n\nUSD figures at the frozen 0.01 lot are informational (capital neutrality). V4 stops are 2–3 ATR structural stops (≈ 10–20 USD at 0.01 lot), so costs are 2–4 % of gross; cost is not what makes these candidates negative.\n`);
W('STRESS_COST_RESULTS.md', `# STRESS COST RESULTS (spread 0.60 + slippage 0.20 USD)\n\n| Split | Candidate | Trades | Normal exp (R) | Stress exp (R) | Stress PF | Degradation (R) |\n|---|---|---|---|---|---|---|\n${S2.flatMap((S) => ['CONTROL', ...CANDS].map((k) => { const v = k === 'CONTROL' ? R[S].control : R[S].candidates[k]; return `| ${S} | ${k === 'CONTROL' ? 'CONTROL' : SNAME[k]} | ${v.stress.n} | ${f(v.expectancy_r)} | ${f(v.stress.expectancy_r)} | ${f(v.stress.pf, 2)} | ${f(v.stress.expectancy_r - v.expectancy_r)} |`; })).join('\n')}\n\nStress costs remove 0.03–0.10 R per trade. Only S7 (n 35) stays positive under stress on HOLDOUT; S1, the only DEV-supported family, is −0.06 R under stress on HOLDOUT. No candidate works only before costs — they do not work after or before.\n`);
W('WALK_FORWARD_RESULTS.md', `# WALK-FORWARD RESULTS (calendar quarters; sequential trades; normal costs)\n\n${S2.map((S) => `## ${S}\n| Candidate | ${Object.keys(R[S].control.walk_forward).join(' | ')} | Quarters > 0 |\n|---|${Object.keys(R[S].control.walk_forward).map(() => '---|').join('')}---|\n${['CONTROL', ...CANDS].map((k) => { const v = k === 'CONTROL' ? R[S].control : R[S].candidates[k]; return `| ${k === 'CONTROL' ? 'CONTROL' : SNAME[k]} | ${Object.keys(R[S].control.walk_forward).map((q) => { const x = v.walk_forward[q]; return x ? `n ${x.n}, ${f(x.expectancy_r)} R, PF ${f(x.pf, 2)}, ${f(x.trades_per_session, 1)}/session` : '—'; }).join(' | ')} | ${pc(v.quarters_positive_share)} |`; }).join('\n')}\n`).join('\n')}\n## Reading\nNo candidate is positive in more than one HOLDOUT quarter except S7 (2 of 3, n 4 and 15). S1 went +0.23 R (DEV) → −0.03 / −0.10 / +0.04 R by quarter; S3 −0.17 / +0.08 / −0.01. Move capture per quarter tracks trade count, not expectancy. Nothing here is period-robust.\n`);
W('PARAMETER_STABILITY.md', `# PARAMETER STABILITY (pre-registered grid neighbours per family; HOLDOUT and DEV; ROBUST = all neighbours positive, SENSITIVE = some ≤ 0, FRAGILE = only centre positive, NEGATIVE_CENTRE)\n\n${Object.keys(DEFN.finalists).map((k) => { const nh = R.HOLD.candidates[k].neighbourhood, nd = R.DEV.candidates[k].neighbourhood; return `## ${SNAME[k]}\n${Object.entries(nh).map(([pk, v]) => `**${pk}** — HOLD ${v.classification ?? '—'}: ${Object.entries(v).filter(([a]) => a !== 'classification' && a !== 'note').map(([a, x]) => `${a} → n ${x.n}, ${f(x.expectancy_r)} R, PF ${f(x.pf, 2)}`).join('; ')}. DEV ${nd[pk]?.classification ?? '—'}: ${Object.entries(nd[pk] ?? {}).filter(([a]) => a !== 'classification' && a !== 'note').map(([a, x]) => `${a} → n ${x.n}, ${f(x.expectancy_r)} R`).join('; ')}.${v.note ? ' ' + v.note : ''}`).join('\n\n')}\n`; }).join('\n')}\n## Reading\nS1's thresholds (compression width, expansion size, variant) were ROBUST / SENSITIVE on DEV and NEGATIVE_CENTRE on HOLD: the whole DEV neighbourhood was a positive plateau that did not exist out of sample — the definition of an unstable region rather than a fragile peak. S7's chase guard is ROBUST on both splits at n 27–35. Every other family is NEGATIVE_CENTRE on both splits. Confirmation-bar variants (C1 → C2 → C3; F1 → F2; D1 → D2; B1 → B2) never turn a negative family positive.\n`);
W('UNCERTAINTY_ANALYSIS.md', `# UNCERTAINTY ANALYSIS (trade bootstrap 2,000 draws seed 20260930; session-block bootstrap 2,000 draws seed 7; month-shuffle adverse sequencing 500 draws)\n\n| Split | Candidate | N | Exp (R) | Trade 95 % CI | Trade 99 % CI (Bonferroni 7) | Block 95 % CI | Block 99 % CI | PF | Top-5 winners share | Max loss streak | Adverse DD p50 / p90 / p99 (R) | Loss streak p50 / p90 |\n|---|---|---|---|---|---|---|---|---|---|---|---|---|\n${S2.flatMap((S) => ['CONTROL', ...CANDS].map((k) => { const v = k === 'CONTROL' ? R[S].control : R[S].candidates[k]; return `| ${S} | ${k === 'CONTROL' ? 'CONTROL' : SNAME[k]} | ${v.n} | ${f(v.expectancy_r)} | ${ci(v.ci95_r)} | ${ci(v.ci99_r)} | ${ci(v.block_ci95_r)} | ${ci(v.block_ci99_r)} | ${f(v.pf, 2)} | ${pc(v.top5_share)} | ${v.max_loss_streak} | ${v.adverse ? `${f(v.adverse.dd_r_p50, 1)} / ${f(v.adverse.dd_r_p90, 1)} / ${f(v.adverse.dd_r_p99, 1)}` : '—'} | ${v.adverse ? `${v.adverse.loss_streak_p50} / ${v.adverse.loss_streak_p90}` : '—'} |`; })).join('\n')}\n\n## Reading\nThe only HOLDOUT CI that excludes zero belongs to S4 (pullback → continuation) and it is entirely NEGATIVE (${ci(R.HOLD.candidates.S4.ci95_r)}). Every N ≥ 200 candidate has a negative point estimate; S7's positive estimate rests on 35 trades with a 95 % CI of ${ci(R.HOLD.candidates.S7.ci95_r)}. No candidate is successful under any reading of the uncertainty.\n`);
W('CONTROL_VS_V4.md', `# CONTROL vs V4 (HOLDOUT, sequential, normal costs)\n\n| Metric | CONTROL | ${SNAME[BEST]} (best V4 by expectancy, N ≥ 200) | S7 trend resumption (only positive V4) |\n|---|---|---|---|\n${[['Trades', (v) => v.n], ['Expectancy (R)', (v) => f(v.expectancy_r)], ['PF', (v) => f(v.pf, 2)], ['Max DD (R)', (v) => f(v.max_dd_r, 2)], ['Trade 95 % CI', (v) => ci(v.ci95_r)], ['Stress exp (R)', (v) => f(v.stress.expectancy_r)], ['Quarters > 0', (v) => pc(v.quarters_positive_share)], ['Move capture', (v) => pc(v.move_capture.capture_rate)], ['Valid (≤ onset) / late', (v) => `${pc(v.move_capture.valid_entry_rate)} / ${pc(v.move_capture.late_entry_rate)}`], ['Wrong direction (events)', (v) => pc(v.move_capture.wrong_direction_rate)], ['NO_SETUP + NO_TRIGGER (events)', (v) => (v.forensics ? pc(v.forensics.rates.NO_SETUP + v.forensics.rates.SETUP_NO_TRIGGER) : pc(v.move_capture.no_setup_or_trigger_rate))], ['False-positive rate (24 bars)', (v) => pc(v.false_move.fp_rate_24)], ['Trades / session (median)', (v) => f(v.trades_per_session?.median)]].map(([k, g]) => `| ${k} | ${g(HC)} | ${g(HB)} | ${g(R.HOLD.candidates.S7)} |`).join('\n')}\n| DEV expectancy (R) | ${f(DC.expectancy_r)} | ${f(DB.expectancy_r)} | ${f(R.DEV.candidates.S7.expectancy_r)} |\n\nV4_BEATS_CONTROL = ${DEC.v4_beats_control}: ${BEST} loses less than CONTROL (${f(HB.expectancy_r)} vs ${f(HC.expectancy_r)} R) with a CI that includes CONTROL, better detection (capture ${pc(HB.move_capture.capture_rate)} vs ${pc(HC.move_capture.capture_rate)}; no-setup/no-trigger ${pc(HB.forensics.rates.NO_SETUP + HB.forensics.rates.SETUP_NO_TRIGGER)} vs ${pc(HC.move_capture.no_setup_or_trigger_rate)}) and the same false-positive rate. Better opportunity detection was achieved; positive economics were not. The directive requires BOTH.\n`);
W('MOVE_CAPTURE_COMPARISON.md', `# MOVE CAPTURE COMPARISON (move event = ≥ 3 × ATR14 within 24 bars before 1 × ATR14 adverse; capture = same-direction unblocked signal within ± 6 bars of onset)\n\n| Split | Candidate | Events | Capture | Valid (≤ onset) | Late | Wrong direction | Already positioned | No signal | of which no setup / no trigger | of which blocked / gated |\n|---|---|---|---|---|---|---|---|---|---|---|\n${S2.flatMap((S) => ['CONTROL', ...CANDS].map((k) => { const v = k === 'CONTROL' ? R[S].control : R[S].candidates[k]; const m = v.move_capture; const ns = v.forensics ? v.forensics.rates.NO_SETUP + v.forensics.rates.SETUP_NO_TRIGGER : m.no_setup_or_trigger_rate; const bl = v.forensics ? v.forensics.rates.TRIGGER_BLOCKED : m.gate_or_filter_rate; return `| ${S} | ${k === 'CONTROL' ? 'CONTROL' : SNAME[k]} | ${m.events} | ${pc(m.capture_rate)} | ${pc(m.valid_entry_rate)} | ${pc(m.late_entry_rate)} | ${pc(m.wrong_direction_rate)} | ${pc(m.already_positioned_rate)} | ${pc(m.no_signal_rate)} | ${pc(ns)} | ${pc(bl)} |`; })).join('\n')}\n\n## Reading\nTwo families detect more moves than production (S3 first break ${pc(R.HOLD.candidates.S3.move_capture.capture_rate)}, S2 sweep-reclaim ${pc(R.HOLD.candidates.S2.move_capture.capture_rate)} vs CONTROL ${pc(HC.move_capture.capture_rate)} on HOLD) by firing 2–3× as often; both lose money. The families that filter (S1, S5, S6, S7) capture 0.2–7 % of moves. Capture and expectancy moved in opposite directions in every family — the trade-off the directive named as failure in both directions.\n`);
W('FALSE_POSITIVE_COMPARISON.md', `# FALSE POSITIVE COMPARISON (signal not followed by a same-direction move onset within −6 … +24 bars)\n\n| Split | Candidate | Signals | FP rate (24 bars) | vs CONTROL | False rate (12 bars) | False-signal exp (R) | Followed-signal exp (R) |\n|---|---|---|---|---|---|---|---|\n${S2.flatMap((S) => ['CONTROL', ...CANDS].map((k) => { const v = k === 'CONTROL' ? R[S].control : R[S].candidates[k]; const fm = v.false_move; const c = R[S].control.false_move.fp_rate_24; return `| ${S} | ${k === 'CONTROL' ? 'CONTROL' : SNAME[k]} | ${fm.signals} | ${pc(fm.fp_rate_24)} | ${k === 'CONTROL' ? '—' : f(fm.fp_rate_24 - c)} | ${pc(fm.false_rate)} | ${f(fm.false_expectancy_r)} | ${f(fm.followed_expectancy_r)} |`; })).join('\n')}\n\n## Reading\nNo V4 family has a materially lower false-positive rate than production (CONTROL ${pc(HC.false_move.fp_rate_24)} on HOLD; V4 ${pc(Math.min(...CANDS.map((k) => R.HOLD.candidates[k].false_move.fp_rate_24)))} – ${pc(Math.max(...CANDS.map((k) => R.HOLD.candidates[k].false_move.fp_rate_24)))}). Roughly half of all confirmed events in XAUUSD 5m are not followed by a 3-ATR move within two hours, whatever the setup. S7's lower rate (${pc(R.HOLD.candidates.S7.false_move.fp_rate_24)}) comes with 38 signals.\n`);

// ---------- V2 verification note / spec / report ----------
W('V3_EVIDENCE_VERIFICATION.md', `# V3 EVIDENCE VERIFICATION (recalculated from source before V4 was pre-registered)\n\n| Claim | Source | Recalculated in V4 |\n|---|---|---|\n| V3 did not demonstrate robust edge; V3-E strongest but inconclusive | research/entry_edge_v3/results/v3_results.json decisions: passing [], EDGE INCONCLUSIVE, V3-E HOLD n 469, +0.117 R, CI [−0.043, +0.279], DEV −0.013 | hashed in results/control_inputs.sha256; read, not re-run |\n| CONTROL move capture HOLD 26.6 % (valid 15.7 %, late 10.9 %) | v3_results.json finalists.HOLD.CONTROL.move_capture | V4 recomputed from the bar array: capture ${pc(HC.move_capture.capture_rate)}, valid ${pc(HC.move_capture.valid_entry_rate)}, late ${pc(HC.move_capture.late_entry_rate)} — identical (asserted) |\n| NO_SETUP_OR_TRIGGER 32.5 % HOLD / 38.0 % DEV (CONTROL) | V1 MISSED_MOVE_FORENSICS, V3 SETUP_TRIGGER_RESULTS | ${pc(HC.move_capture.no_setup_or_trigger_rate)} / ${pc(DC.move_capture.no_setup_or_trigger_rate)} — identical |\n| WRONG_DIRECTION 20.2 % HOLD / 18.5 % DEV | same | ${pc(HC.move_capture.wrong_direction_rate)} / ${pc(DC.move_capture.wrong_direction_rate)} — identical |\n| LATE_ENTRY 10.9 % HOLD / 8.3 % DEV | same | ${pc(HC.move_capture.late_entry_rate)} / ${pc(DC.move_capture.late_entry_rate)} — identical |\n| 60–76 % of moves have no setup/trigger under V3 subsets | V3 SETUP_TRIGGER_RESULTS | not re-run (subset filters, superseded by V4's own forensics) |\n| V2: no structure event within 3 bars before ~78 % of moves; move IS the first structural evidence | V2 SETUP_TRIGGER_DIAGNOSIS | V4 pre-move research confirms with 29 features: no lift > 1.3 except the onset candle's own size/body |\n\nThe move-event set (1,640 / 1,842) and the CONTROL statistics were reproduced exactly from the hashed inputs; the production source for regime, setup, trigger, MC/PB/BO/SR/MR, quality, MTF, overextension and RR was read (SETUP_TRIGGER_ARCHITECTURE.md) rather than summarised.\n`);
W('ENTRY_CORE_V4_SPEC.md', `# ENTRY CORE V4 — IMPLEMENTATION SPEC (NOT IMPLEMENTED: no candidate passed; kept so any future passing setup/trigger can be ported deterministically)\n\n1. Inputs at the confirmed 5m close: the confirmed bar array (≥ 400 bars), the production 30m regime label (family G only). Nothing from the forming bar.\n2. Feature layer (pure functions of bars ≤ t): ATR14 (simple), trailing-288 ATR percentile, 12/24/36-bar ranges, EMA20/50, mom3/6/12, acceleration, body/close location, 3/3 pivots known at pivot + 3, sweeps, first breaks.\n3. Setup layer: one boolean (+ direction) per family exactly as SETUP_TRIGGER_ARCHITECTURE.md; evaluated at t − 1 for the trigger at t.\n4. Trigger layer: the family's event at t; produces {side, entry = close, structural stop, origin, displacement}.\n5. Geometry/gates: stop floored at 0.5 ATR, rejected > 3 ATR (RISK), ATR ≥ 2 USD, family chase guard; TP = entry ± 1.70 × risk. Blocked triggers are logged with their reason and never re-tried for that candle.\n6. Pipeline position: parallel to (not inside) the production model stack, AFTER the watcher's confirmed-candle acquisition and BEFORE the executor; every executor gate (identity, dedup, freshness, one position, breakers, spread, drift, News V2, sizing, margin, broker SL) unchanged.\n7. Parity fixtures before wiring: ≥ 200 recorded live candles → identical features, setup states, triggers, geometry, block reasons versus replay.\n8. Rollback: a single mode flag (OFF by default) in an unwired module; no registry file touched.\n\nStatus: SPEC ONLY. EDGE_DEMONSTRATED = ${DEC.edge_demonstrated}; no runtime module was written; nothing was wired.\n`);
